const ELEMENT_PROP_KEYS = new Set(["theme","lead","interval","swapAt","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  lead: "Wheels up",
  interval: 30,
  swapAt: 36,
  fontFamily: "Red Hat Display",
  scale: 1,
  delay: 0,
  speed: 1,
};

type OnApproachElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OnApproachBase>;

const OnApproachInner = forwardRef<
  HTMLDivElement,
  OnApproachElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<OnApproach>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OnApproachBase
          {...(componentProps as unknown as ComponentProps<typeof OnApproachBase>)}
        />
      </div>
    </Sequence>
  );
});

export const OnApproach = Interactive.withSchema({
  Component: OnApproachInner,
  componentName: "<OnApproach>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
